package br.com.orientec.backend.adapter.out.persistence.entity.os; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; @Entity @Table(name="ordem_servico_orcamento") public class OrdemServicoOrcamento { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id") private Long id; @Column(name="ordem_servico_id") private Long ordemServicoId; @Column(name="valor_pecas") private java.math.BigDecimal valorPecas; @Column(name="valor_servico") private java.math.BigDecimal valorServico; @Column(name="desconto") private java.math.BigDecimal desconto; @Column(name="valor_total") private java.math.BigDecimal valorTotal; @Column(name="data_orcamento") private java.time.OffsetDateTime dataOrcamento; @Column(name="usuario_codigo") private Long usuarioCodigo; @Column(name="observacao") private String observacao; public OrdemServicoOrcamento(){}  public Long getId(){return id;} public void setId(Long v){this.id=v;} public Long getOrdemServicoId(){return ordemServicoId;} public void setOrdemServicoId(Long v){this.ordemServicoId=v;} public java.math.BigDecimal getValorPecas(){return valorPecas;} public void setValorPecas(java.math.BigDecimal v){this.valorPecas=v;} public java.math.BigDecimal getValorServico(){return valorServico;} public void setValorServico(java.math.BigDecimal v){this.valorServico=v;} public java.math.BigDecimal getDesconto(){return desconto;} public void setDesconto(java.math.BigDecimal v){this.desconto=v;} public java.math.BigDecimal getValorTotal(){return valorTotal;} public void setValorTotal(java.math.BigDecimal v){this.valorTotal=v;} public java.time.OffsetDateTime getDataOrcamento(){return dataOrcamento;} public void setDataOrcamento(java.time.OffsetDateTime v){this.dataOrcamento=v;} public Long getUsuarioCodigo(){return usuarioCodigo;} public void setUsuarioCodigo(Long v){this.usuarioCodigo=v;} public String getObservacao(){return observacao;} public void setObservacao(String v){this.observacao=v;} }
